"""Record the assistant's direct text review of READ40.md; no visual GT claim."""
import csv,json,hashlib
from pathlib import Path
W=Path(__file__).resolve().parent;O=W/'out'
# Explicit labels transcribed after reading all forty questions, forward lines,
# option lists and selected letters. These are not generated by the parser.
labels='''away easy lateral left
away hard front back-left
away hard behind front-left
toward easy lateral right
toward hard behind back-left
toward hard front front-right
toward medium behind back
toward medium front right
away easy lateral left
away hard front back-right
away hard behind front-left
away medium front back
away medium lateral right
toward easy lateral right
toward hard behind back-right
toward hard front front-left
toward medium behind back
toward medium lateral left
toward hard front front-left
toward hard front front-left
toward hard front front-left
toward medium front right
toward medium front left
toward medium front right
toward medium behind back
toward easy lateral right
toward easy lateral right
away medium front back
away easy lateral right
away hard front back-left
away hard behind front-right
away medium lateral left
toward easy lateral left
toward hard behind back-right
toward hard front front-left
toward medium lateral left
away easy lateral right
away hard front back-right
away hard behind front-right
away easy lateral right'''.splitlines()
with (O/'READ40_KEYS.tsv').open() as f:rows=list(csv.DictReader(f,delimiter='\t'))
assert len(rows)==len(labels)==40
checked=[]
for row,label in zip(rows,labels):
 expected=label.split();actual=[row[k] for k in ['clause','difficulty','forward_relation','answer_label']]
 assert expected==actual,(row['number'],expected,actual)
 checked.append(dict(number=int(row['number']),qid=row['qid'],manual_labels=expected,agreement=True))
def pin(p):return dict(path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
result=dict(status='MANUAL_TEXT_REVIEW_COMPLETE',reviewer='primary assistant',method='Direct reading of all forty printed questions, stated forward relations, selected answer letters and options; independent labels are literal in manual_review.py.',checked=40,disagreements=0,visual_ground_truth_checked=False,inputs=[pin(p) for p in [Path(__file__),O/'READ40.md',O/'READ40_KEYS.tsv',O/'SOURCE_CENSUS.json',W/'parse_direction.py']],rows=checked)
(O/'MANUAL_REVIEW.json').write_text(json.dumps(result,indent=2)+'\n')
print('40 manual labels agree; no visual ground-truth claim.')
